from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];OUT=ROOT/'deliverables/delta_20261020';SCRIPT='drafts/delta_20261020/agent_a/finish_a.py'
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def save(rel,x):
 p=OUT/rel;p.parent.mkdir(parents=True,exist_ok=True);assert not p.exists();p.write_text(json.dumps(x,indent=2,sort_keys=True)+'\n',encoding='utf-8')
