 for variant in sorted({r['variant']for r in rr}):
  v=[r for r in rr if r['variant']==variant];bad=[r for r in v if r['verdicts']['I0']!=r['verdicts']['I1']];dec=[r for r in bad if any(r['verdicts']['I0'][k]!=r['verdicts']['I1'][k]for k in('decision','provider','action'))]
  if bad:rows.append({'run':run,'category':variant,'classification':classification[variant],'probes':len(v),'disagreement_probes':len(bad),'decision_provider_action_disagreements':len(dec),'reason_only_disagreements':len(bad)-len(dec),'distinct_rooms':len({r['room']for r in v})})
