mentions=[]
for p in [ROOT/'HANDOVER.md',*sorted((ROOT/'docs').glob('*.md'))]:
 for i,line in enumerate(p.read_text(encoding='utf-8-sig').splitlines(),1):
  if re.search(r'(?<![a-zA-Z0-9])720(?![a-zA-Z0-9])',line):mentions.append({'path':p.relative_to(ROOT).as_posix(),'line':i,'text':line,'literal_720_bugs':bool(re.search(r'720\s*(?:distinct\s+)?bugs?',line,re.I)),'clarification':'Disagreement probes within one authored room, not bug count.'})
